package run.ikaros.planning; import java.time.Instant; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; import run.ikaros.common.ConflictException; import run.ikaros.common.NotFoundException;
@Service public class PersistentPlanningCommentService implements PlanningCommentService {private final PlanningCommentRepository comments;private final PlanningTaskRepository tasks;private final PlanningProjectRepository projects;private final PlanningGoalRepository goals; public PersistentPlanningCommentService(PlanningCommentRepository c,PlanningTaskRepository t,PlanningProjectRepository p,PlanningGoalRepository g){comments=c;tasks=t;projects=p;goals=g;} public Mono<PlanningCommentView> create(UUID author,CreatePlanningCommentRequest r){return target(author,r.targetType(),r.targetId()).then(Mono.defer(()->{Instant n=Instant.now();return comments.save(new PlanningCommentEntity(null,author,r.targetType(),r.targetId(),r.content().trim(),n,n,null,null)).map(this::view);}));} public Flux<PlanningCommentView> list(UUID owner,PlanningCommentTargetType type,UUID id){return target(owner,type,id).thenMany(comments.findAllByTargetTypeAndTargetIdAndDeletedAtIsNullOrderByCreatedAtAsc(type,id)).map(this::view);} public Mono<PlanningCommentView> update(UUID author,UUID id,UpdatePlanningCommentRequest r){return owned(author,id).flatMap(old->{if(old.deletedAt()!=null)return Mono.error(new ConflictException("已删除评论不能修改"));if((old.version()==null?0:old.version())!=r.expectedVersion())return Mono.error(new ConflictException("Comment 版本冲突"));return comments.save(new PlanningCommentEntity(old.id(),old.authorId(),old.targetType(),old.targetId(),r.content().trim(),old.createdAt(),Instant.now(),null,old.version()));}).map(this::view);} public Mono<Void> delete(UUID author,UUID id){return owned(author,id).flatMap(old->comments.save(new PlanningCommentEntity(old.id(),old.authorId(),old.targetType(),old.targetId(),old.content(),old.createdAt(),old.updatedAt(),Instant.now(),old.version()))).then();} private Mono<Void> target(UUID owner,PlanningCommentTargetType type,UUID id){return switch(type){case TASK->tasks.findById(id).filter(x->x.ownerId().equals(owner)).switchIfEmpty(Mono.error(new NotFoundException("Target 不存在"))).then();case PROJECT->projects.findById(id).filter(x->x.ownerId().equals(owner)).switchIfEmpty(Mono.error(new NotFoundException("Target 不存在"))).then();case GOAL->goals.findById(id).filter(x->x.ownerId().equals(owner)).switchIfEmpty(Mono.error(new NotFoundException("Target 不存在"))).then();};} private Mono<PlanningCommentEntity> owned(UUID author,UUID id){return comments.findById(id).filter(x->x.authorId().equals(author)).switchIfEmpty(Mono.error(new NotFoundException("Comment 不存在")));} private PlanningCommentView view(PlanningCommentEntity x){return new PlanningCommentView(x.id(),x.authorId(),x.targetType(),x.targetId(),x.content(),x.createdAt(),x.updatedAt(),x.deletedAt(),x.version()==null?0:x.version());}}
